using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class RecoveredAirSceneImporter {
 const string Dst="Assets/RecoveredS07/Environment/";
 public static RecoveredAirControls Import(){
  var b=JsonUtility.FromJson<S07RecoveryImporter.Blueprint>(File.ReadAllText("Assets/Recovery/ExtraScene/Air/blueprint.json"));var meshes=new Dictionary<string,Mesh>();var textures=new Dictionary<string,Texture2D>();var materials=new Dictionary<string,Material>();
  foreach(var entry in b.meshes){var d=JsonUtility.FromJson<S07RecoveryImporter.MeshData>(File.ReadAllText(entry.file));var mesh=new Mesh{name=d.name};mesh.vertices=d.vertices;if(d.normals.Length==d.vertices.Length)mesh.normals=d.normals;if(d.uv.Length==d.vertices.Length)mesh.uv=d.uv;mesh.subMeshCount=d.submeshes.Length;for(int i=0;i<d.submeshes.Length;i++)mesh.SetTriangles(d.submeshes[i].indices,i);mesh.RecalculateBounds();Save(mesh,Dst+"AirMesh_"+entry.id+".asset");meshes[entry.id]=mesh;}
  foreach(var entry in b.textures){var i=(TextureImporter)AssetImporter.GetAtPath(entry.file);i.sRGBTexture=entry.colorSpace==1;i.filterMode=(FilterMode)entry.filterMode;i.wrapModeU=(TextureWrapMode)entry.wrapU;i.wrapModeV=(TextureWrapMode)entry.wrapV;i.textureCompression=TextureImporterCompression.Uncompressed;i.SaveAndReimport();textures[entry.id]=AssetDatabase.LoadAssetAtPath<Texture2D>(entry.file);}
  foreach(var entry in b.materials){var shader=Shader.Find("Recovered/"+entry.shaderName+"/Variant1");if(shader==null||ShaderUtil.ShaderHasError(shader))throw new InvalidOperationException("Air shader failed: "+entry.shaderName);var m=new Material(shader){name=entry.name,renderQueue=entry.renderQueue};foreach(var c in entry.colors)if(m.HasProperty(c.name))m.SetColor(c.name,c.value);foreach(var f in entry.floats)if(m.HasProperty(f.name))m.SetFloat(f.name,f.value);foreach(var t in entry.textures){m.SetTexture(t.name,textures[t.texture]);m.SetTextureScale(t.name,t.scale);m.SetTextureOffset(t.name,t.offset);}Save(m,Dst+"AirMaterial_"+entry.id+".mat");materials[entry.id]=m;}
  var root=new GameObject("NativeAirDisplay").AddComponent<RecoveredAirControls>();root.air=materials["2"];root.seats5=materials["13"];root.seats6=materials["14"];root.seats=root.seats5;foreach(var n in b.nodes){var go=new GameObject(n.name);if(n.name=="5S"||n.name=="6S")go.layer=8;go.transform.SetParent(root.transform,false);go.transform.localPosition=n.position;go.transform.localRotation=n.rotation;go.transform.localScale=n.scale;go.AddComponent<MeshFilter>().sharedMesh=meshes[n.mesh];var r=go.AddComponent<MeshRenderer>();r.sharedMaterials=Array.ConvertAll(n.materials,id=>materials[id]);if(n.name=="5S")root.render5=r;if(n.name=="6S")root.render6=r;}root.SetSixSeats(false);root.SetVisible(false);return root;
 }
 static void Save(UnityEngine.Object obj,string path){AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(obj,path);}
}
